import {
  showErrorMessage,
  showSuccessMessage,
} from '/static/js/common/notification.prod.js';
document.addEventListener('DOMContentLoaded', function () {
  let e = document.querySelector('[name=csrftoken]').content;
  ($('.actionButton').on('click', function () {
    $('.mobileHeaderContent').hasClass('animate__fadeInDown')
      ? ($('.mobileHeaderContent')
          .removeClass('animate__fadeInDown')
          .addClass('animate__fadeOutUp'),
        $('#header').toggleClass('darken', !1))
      : ($('.mobileHeaderContent')
          .removeClass('animate__fadeOutUp')
          .addClass('animate__fadeInDown'),
        $('#header').toggleClass('darken', !0));
  }),
    $('.mobileHeaderContent').on('click', function () {
      ($(this)
        .removeClass('animate__fadeInDown')
        .addClass('animate__fadeOutUp'),
        $('#header').toggleClass('darken', !1));
    }),
    $('.newsletter-button').on('click', function () {
      let e = $('.newsletter-input-container').find('input');
      if (e.val()) {
        let t = $('.modal-container');
        (t.find('#modalHeader').text('Join Our Newsletter'),
          t
            .find('.modalContentHolder')
            .append(
              $(
                `<div class="inputHolder"><input type="text" id="newsletterEmail" value="${e.val()}"></div>`
              )
            )
            .append(
              $(
                '\n            <div class="inputHolder flex">\n                <div class="modalInput">\n                    <input type="text" id="newsletterFirstName" placeholder="Enter your First Name">\n                </div>\n                <div class="modalInput">\n                    <input type="text" id="newsletterLastName" placeholder="Enter your Last Name">\n                </div>\n            </div>\n            '
              )
            ),
          t.removeClass('animate__fadeOut').toggleClass('animate__fadeIn', !0),
          $('#modal-value').val('newsletter'));
      } else showErrorMessage('Invalid Email', 'Kindly enter a valid email.');
    }),
    $('#cancel').on('click', function () {
      $('.modal-container')
        .removeClass('animate__fadeIn')
        .addClass('animate__fadeOut')
        .one('animationend', function () {
          ($(this).find('#modalHeader').text(''),
            $(this).find('.modalContentHolder').empty());
        });
    }),
    $('#accept').on('click', function () {
      let t = $('#modal-value').val(),
        a = $('#newsletterEmail').val().trim(),
        n = $('#newsletterFirstName').val().trim(),
        o = $('#newsletterLastName').val().trim();
      ((n = n.charAt(0).toUpperCase() + n.slice(1)),
        (o = o.charAt(0).toUpperCase() + o.slice(1)),
        'newsletter' == t &&
          a &&
          n &&
          o &&
          $.ajax({
            type: 'POST',
            headers: { 'X-CSRFToken': e },
            contentType: 'application/json',
            data: JSON.stringify({ email: a, firstName: n, lastName: o }),
            processData: !1,
            url: '/users/?action=register-newsletter',
            success: function () {
              showSuccessMessage(
                gettext('Subscribed'),
                gettext('You have successfully subscribed to SmSt Newsletter')
              );
            },
            error: function () {},
          }));
    }),
    localStorage.getItem('cookie_acceptance') || $('#cookie_banner').fadeIn(),
    $('#accept_cookies').on('click', function () {
      $('.cookie_policy_holder')
        .removeClass('animate__fadeInUp')
        .addClass('animate__fadeOutDown')
        .one('animationend', function () {
          (localStorage.setItem('cookie_acceptance', !0),
            showSuccessMessage(
              'Cookie Preference Set',
              'You have accepted our Cookie Policy'
            ),
            $('#cookie_banner').remove());
        });
    }));
});
